      array('n'=>'s1614_e4_taisyti_35434','u'=>admin_url('admin.php?page=ps-desk&eile=klausimai'),'w'=>1400,'click'=>'.dl-kortele[data-id="35434"] button[data-redaguoti]','eval'=>$evf)
